'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import {
  INVITATIONS,
  MEMBERS,
  OPEN_TASKS,
  TEAM_NAME,
  type Invitation,
  type Member,
  type MemberTask,
  type Role,
  type StatusId,
} from './data';
import { InvitationRow } from './invitation-row';
import { InvitePopover } from './invite-popover';
import { MemberCard, type MemberActions } from './member-card';
import { MEMBER_GRID } from './member-parts';

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ITEM_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ITEM_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const COLUMN_LABELS = [
  { id: 'member', label: 'Member', isFigure: false },
  { id: 'task', label: 'Current task', isFigure: false },
  { id: 'worked', label: 'Worked today', isFigure: true },
  { id: 'estimate', label: 'Estimate', isFigure: true },
  { id: 'total', label: 'Total today', isFigure: true },
];

function itemVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ITEM_FADE;
  }
  return ITEM_PRESENCE;
}

function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

function matchesQuery(text: string, query: string) {
  return text.toLowerCase().includes(query);
}

function updateMember(
  members: Member[],
  memberId: string,
  change: (member: Member) => Member
) {
  return members.map((member) => {
    if (member.id !== memberId) {
      return member;
    }
    return change(member);
  });
}

function withAddedTime(member: Member, minutes: number): Member {
  const task = member.task;
  if (!task) {
    return member;
  }
  const hasEntry = member.activity.some((entry) => entry.taskId === task.id);
  if (!hasEntry) {
    const entry = {
      taskId: task.id,
      number: task.number,
      title: task.title,
      minutes,
    };
    return { ...member, activity: [entry, ...member.activity] };
  }
  const activity = member.activity.map((entry) => {
    if (entry.taskId !== task.id) {
      return entry;
    }
    return { ...entry, minutes: entry.minutes + minutes };
  });
  return { ...member, activity };
}

function ColumnLabels() {
  return (
    <div
      aria-hidden='true'
      className={cn(
        MEMBER_GRID,
        'text-muted-foreground hidden h-9 text-xs font-medium xl:grid'
      )}
    >
      {COLUMN_LABELS.map((column, index) => {
        const isFirst = index === 0;

        return (
          <span
            key={column.id}
            className={cn(
              'border-border flex items-center px-4',
              !isFirst && 'hairline-l',
              column.isFigure && 'justify-center'
            )}
          >
            {column.label}
          </span>
        );
      })}
      <span className='hairline-l border-border' />
    </div>
  );
}

export default function Team01() {
  const [members, setMembers] = useState<Member[]>(MEMBERS);
  const [invitations, setInvitations] = useState<Invitation[]>(INVITATIONS);
  const [openTasks, setOpenTasks] = useState<MemberTask[]>(OPEN_TASKS);
  const [query, setQuery] = useState('');
  const shouldReduceMotion = useReducedMotion();
  const itemVariants = itemVariantsOf(shouldReduceMotion);

  const normalizedQuery = query.trim().toLowerCase();
  const hasQuery = normalizedQuery.length > 0;
  const visibleMembers = members.filter((member) =>
    matchesQuery(member.name, normalizedQuery)
  );
  const visibleInvitations = invitations.filter((invitation) =>
    matchesQuery(invitation.email, normalizedQuery)
  );
  const visibleCount = visibleMembers.length + visibleInvitations.length;
  const isEmptySearch = hasQuery && visibleCount === 0;
  const trackingCount = members.filter(
    (member) => member.presence === 'tracking'
  ).length;
  const memberCountText = countLabel(members.length, 'member', 'members');
  const trackingText = countLabel(
    trackingCount,
    'person tracking time',
    'people tracking time'
  );
  const takenEmails = invitations.map((invitation) => invitation.email);

  function returnTask(task: MemberTask | null) {
    if (!task) {
      return;
    }
    setOpenTasks((previous) => [task, ...previous]);
  }

  const actions: MemberActions = {
    assignTask(memberId, task) {
      setOpenTasks((previous) =>
        previous.filter((candidate) => candidate.id !== task.id)
      );
      setMembers((previous) =>
        updateMember(previous, memberId, (member) => ({
          ...member,
          task,
          estimateMinutes: 0,
        }))
      );
    },
    unassignTask(memberId) {
      const member = members.find((candidate) => candidate.id === memberId);
      returnTask(member?.task ?? null);
      setMembers((previous) =>
        updateMember(previous, memberId, (current) => ({
          ...current,
          task: null,
          estimateMinutes: 0,
        }))
      );
    },
    changeStatus(memberId, status: StatusId) {
      setMembers((previous) =>
        updateMember(previous, memberId, (member) => {
          if (!member.task) {
            return member;
          }
          return { ...member, task: { ...member.task, status } };
        })
      );
    },
    changeEstimate(memberId, minutes) {
      setMembers((previous) =>
        updateMember(previous, memberId, (member) => ({
          ...member,
          estimateMinutes: minutes,
        }))
      );
    },
    addTime(memberId, minutes) {
      setMembers((previous) =>
        updateMember(previous, memberId, (member) =>
          withAddedTime(member, minutes)
        )
      );
    },
    changeRole(memberId, role: Role) {
      setMembers((previous) =>
        updateMember(previous, memberId, (member) => ({ ...member, role }))
      );
    },
    removeMember(memberId) {
      const member = members.find((candidate) => candidate.id === memberId);
      returnTask(member?.task ?? null);
      setMembers((previous) =>
        previous.filter((candidate) => candidate.id !== memberId)
      );
    },
  };

  function changeQuery(event: React.ChangeEvent<HTMLInputElement>) {
    setQuery(event.target.value);
  }

  function clearQuery() {
    setQuery('');
  }

  function invite(email: string) {
    const invitation: Invitation = {
      id: `invite-${email}`,
      email,
      role: 'member',
      sentLabel: 'Sent just now',
    };
    setInvitations((previous) => [...previous, invitation]);
  }

  function resendInvitation(invitationId: string) {
    setInvitations((previous) =>
      previous.map((invitation) => {
        if (invitation.id !== invitationId) {
          return invitation;
        }
        return { ...invitation, sentLabel: 'Sent again just now' };
      })
    );
  }

  function revokeInvitation(invitationId: string) {
    setInvitations((previous) =>
      previous.filter((invitation) => invitation.id !== invitationId)
    );
  }

  return (
    <div className='bg-background text-foreground flex min-h-dvh w-full flex-col'>
      <div className='hairline-b border-border flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
        <div className='flex min-w-0 items-baseline gap-2'>
          <h1 className='truncate text-lg font-semibold'>{`${TEAM_NAME} team`}</h1>
          <span className='text-muted-foreground text-xs tabular-nums'>
            {`${memberCountText} · ${trackingText}`}
          </span>
        </div>
        <div className='flex w-full items-center gap-2 sm:ml-auto sm:w-auto'>
          <div className='relative min-w-0 flex-1 sm:w-56 sm:flex-none'>
            <SearchIcon className='text-muted-foreground pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2' />
            <Input
              type='search'
              value={query}
              placeholder='Search people'
              aria-label='Search members and invitations'
              onChange={changeQuery}
              className='pl-8'
            />
          </div>
          <InvitePopover
            teamName={TEAM_NAME}
            takenEmails={takenEmails}
            onInvite={invite}
          />
        </div>
      </div>
      <div className='flex flex-col gap-3 px-4 pt-3 pb-6 md:px-6'>
        <ColumnLabels />
        {isEmptySearch && (
          <div className='hairline-border border-foreground/20 flex flex-col items-center gap-3 rounded-xl border-dashed px-4 py-12 text-center'>
            <div className='flex flex-col gap-1'>
              <p className='text-sm font-medium'>
                {`No member or invitation matches “${query.trim()}”`}
              </p>
              <p className='text-muted-foreground text-[13px]'>
                Search by first name, last name or e-mail address
              </p>
            </div>
            <Button variant='outline' onClick={clearQuery}>
              <XIcon />
              Clear search
            </Button>
          </div>
        )}
        <ul className='flex flex-col'>
          <AnimatePresence initial={false}>
            {visibleMembers.map((member) => (
              <motion.li
                key={member.id}
                variants={itemVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <div className='pb-2'>
                  <MemberCard
                    member={member}
                    openTasks={openTasks}
                    actions={actions}
                  />
                </div>
              </motion.li>
            ))}
            {visibleInvitations.map((invitation) => (
              <motion.li
                key={invitation.id}
                variants={itemVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <div className='pb-2'>
                  <InvitationRow
                    invitation={invitation}
                    onResend={resendInvitation}
                    onRevoke={revokeInvitation}
                  />
                </div>
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useId, useState } from 'react';

import {
  ChartLineIcon,
  ChevronDownIcon,
  EllipsisIcon,
  PlusIcon,
  ShieldCheckIcon,
  TrashIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import {
  ROLE_LABEL,
  type Member,
  type MemberTask,
  type Role,
  type StatusId,
} from './data';
import { EstimateField } from './estimate-field';
import {
  FIGURE_LABEL,
  IssueTypeGem,
  MEMBER_CARD_HEIGHT,
  MEMBER_GRID,
  PresenceAvatar,
  SlidingValue,
  StatusChipMenu,
  formatDuration,
  totalTodayOf,
  workedTodayOf,
} from './member-parts';

export type MemberActions = {
  assignTask: (memberId: string, task: MemberTask) => void;
  unassignTask: (memberId: string) => void;
  changeStatus: (memberId: string, status: StatusId) => void;
  changeEstimate: (memberId: string, minutes: number) => void;
  addTime: (memberId: string, minutes: number) => void;
  changeRole: (memberId: string, role: Role) => void;
  removeMember: (memberId: string) => void;
};

const OWN_CARD =
  'ring-primary/45 shadow-[0_6px_18px_-8px_color-mix(in_oklab,var(--primary)_45%,transparent)]';

const QUICK_TIME = [15, 30, 60];

const TASK_SWAP_TRANSITION: Transition = {
  duration: 0.18,
  ease: [0.23, 1, 0.32, 1],
};

const TASK_SWAP: Variants = {
  enter: { opacity: 0, y: 6 },
  visible: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -6 },
};

const PANEL_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PANEL_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const PANEL_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, transition: PANEL_OUT },
  shown: { height: 'auto', opacity: 1, transition: PANEL_IN },
};

const FADE: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
  hidden: { opacity: 0, transition: PANEL_OUT },
  shown: { opacity: 1, transition: PANEL_IN },
};

const ROLES: Role[] = ['manager', 'member', 'viewer'];

function taskSwapOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE;
  }
  return TASK_SWAP;
}

function panelPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE;
  }
  return PANEL_PRESENCE;
}

function controlsOf(isOpen: boolean, panelId: string) {
  if (isOpen) {
    return panelId;
  }
  return undefined;
}

function isRole(value: unknown): value is Role {
  return ROLES.some((role) => role === value);
}

function shareOf(minutes: number, total: number) {
  if (total === 0) {
    return 0;
  }
  return Math.round((minutes / total) * 100);
}

function quickTimeLabelOf(minutes: number) {
  if (minutes < 60) {
    return `+${minutes}m`;
  }
  return `+${minutes / 60}h`;
}

function AssignTaskMenu({
  member,
  openTasks,
  onAssign,
}: {
  member: Member;
  openTasks: MemberTask[];
  onAssign: (task: MemberTask) => void;
}) {
  const hasOpenTasks = openTasks.length > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Assign a task to ${member.name}`}
            className='hairline-border border-foreground/20 hover:border-foreground/35 text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 data-popup-open:border-foreground/35 inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-md border-dashed px-2.5 text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]'
          />
        }
      >
        <PlusIcon className='size-3.5' />
        Assign task
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-80'>
        <DropdownMenuLabel>Open tasks</DropdownMenuLabel>
        {!hasOpenTasks && (
          <DropdownMenuItem disabled>
            No open task left to assign
          </DropdownMenuItem>
        )}
        {openTasks.map((task) => {
          function assign() {
            onAssign(task);
          }

          return (
            <DropdownMenuItem key={task.id} onClick={assign}>
              <IssueTypeGem type={task.type} />
              <span className='text-muted-foreground text-xs tabular-nums'>
                {task.number}
              </span>
              <span className='min-w-0 flex-1 truncate'>{task.title}</span>
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function TaskCell({
  member,
  openTasks,
  actions,
}: {
  member: Member;
  openTasks: MemberTask[];
  actions: MemberActions;
}) {
  const shouldReduceMotion = useReducedMotion();
  const variants = taskSwapOf(shouldReduceMotion);
  const task = member.task;
  let swapKey = 'no-task';
  if (task) {
    swapKey = task.id;
  }

  function assign(nextTask: MemberTask) {
    actions.assignTask(member.id, nextTask);
  }

  function changeStatus(status: StatusId) {
    actions.changeStatus(member.id, status);
  }

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.div
        key={swapKey}
        variants={variants}
        initial='enter'
        animate='visible'
        exit='exit'
        transition={TASK_SWAP_TRANSITION}
        className='flex min-w-0 flex-col gap-1.5'
      >
        {task && (
          <>
            <div className='flex min-w-0 items-center gap-2'>
              <IssueTypeGem type={task.type} />
              <span className='text-muted-foreground text-xs tabular-nums'>
                {task.number}
              </span>
              <StatusChipMenu
                status={task.status}
                taskNumber={task.number}
                onChange={changeStatus}
              />
            </div>
            <p className='line-clamp-2 text-[13px] leading-snug'>
              {task.title}
            </p>
          </>
        )}
        {!task && (
          <div className='flex items-center gap-3'>
            <AssignTaskMenu
              member={member}
              openTasks={openTasks}
              onAssign={assign}
            />
            <span className='text-muted-foreground hidden text-xs sm:inline'>
              No task in progress
            </span>
          </div>
        )}
      </motion.div>
    </AnimatePresence>
  );
}

function MemberMenu({
  member,
  actions,
}: {
  member: Member;
  actions: MemberActions;
}) {
  const task = member.task;
  const canRemove = !member.isCurrentUser;

  function unassign() {
    actions.unassignTask(member.id);
  }

  function changeRole(value: unknown) {
    if (isRole(value)) {
      actions.changeRole(member.id, value);
    }
  }

  function remove() {
    actions.removeMember(member.id);
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label={`Actions for ${member.name}`}
            className='text-muted-foreground'
          />
        }
      >
        <EllipsisIcon />
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-56'>
        {task && (
          <DropdownMenuItem onClick={unassign}>
            <XIcon />
            {`Unassign ${task.number}`}
          </DropdownMenuItem>
        )}
        <DropdownMenuSub>
          <DropdownMenuSubTrigger>
            <ShieldCheckIcon />
            Change role
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            <DropdownMenuRadioGroup
              value={member.role}
              onValueChange={changeRole}
            >
              {ROLES.map((role) => (
                <DropdownMenuRadioItem key={role} value={role} closeOnClick>
                  {ROLE_LABEL[role]}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuSubContent>
        </DropdownMenuSub>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant='destructive'
          disabled={!canRemove}
          onClick={remove}
        >
          <TrashIcon />
          Remove from team
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function ActivityPanel({
  member,
  panelId,
  actions,
}: {
  member: Member;
  panelId: string;
  actions: MemberActions;
}) {
  const total = totalTodayOf(member);
  const task = member.task;
  const hasActivity = member.activity.length > 0;

  return (
    <div
      id={panelId}
      className='hairline-t border-border flex flex-col gap-3 border-dashed px-4 py-3'
    >
      <p className='text-muted-foreground text-xs font-medium'>Today</p>
      {!hasActivity && (
        <p className='text-muted-foreground text-[13px]'>
          No time tracked today
        </p>
      )}
      {hasActivity && (
        <ul className='flex flex-col gap-2.5'>
          {member.activity.map((entry) => {
            const share = shareOf(entry.minutes, total);
            const barStyle = { width: `${share}%` } as React.CSSProperties;

            return (
              <li
                key={entry.taskId}
                className='grid grid-cols-[1fr_auto] items-center gap-x-4 gap-y-1.5 sm:grid-cols-[minmax(0,1fr)_8rem_4.5rem_2.5rem]'
              >
                <span className='flex min-w-0 items-center gap-2 text-[13px]'>
                  <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
                    {entry.number}
                  </span>
                  <span className='truncate'>{entry.title}</span>
                </span>
                <span className='bg-foreground/[0.06] col-span-2 h-1 overflow-hidden rounded-full sm:col-span-1'>
                  <span
                    style={barStyle}
                    className='bg-primary block h-full rounded-full transition-[width] duration-300 ease-(--ease-out-strong)'
                  />
                </span>
                <SlidingValue
                  value={entry.minutes}
                  className='row-start-1 justify-end text-[13px] font-medium sm:row-auto'
                />
                <span className='text-muted-foreground hidden text-right text-xs tabular-nums sm:block'>
                  {`${share}%`}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      {task && (
        <div className='flex flex-wrap items-center gap-2'>
          <span className='text-muted-foreground text-xs'>
            {`Add time to ${task.number}`}
          </span>
          {QUICK_TIME.map((minutes) => {
            function addTime() {
              actions.addTime(member.id, minutes);
            }

            return (
              <Button
                key={minutes}
                variant='secondary'
                size='sm'
                onClick={addTime}
                className='tabular-nums'
              >
                {quickTimeLabelOf(minutes)}
              </Button>
            );
          })}
        </div>
      )}
    </div>
  );
}

type MemberCardProps = {
  member: Member;
  openTasks: MemberTask[];
  actions: MemberActions;
};

export function MemberCard({ member, openTasks, actions }: MemberCardProps) {
  const [isActivityOpen, setIsActivityOpen] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const panelVariants = panelPresenceOf(shouldReduceMotion);
  const panelId = useId();
  const task = member.task;
  const worked = workedTodayOf(member);
  const total = totalTodayOf(member);
  const isManager = member.role === 'manager';
  const activityLabel = `Today’s activity of ${member.name}: ${formatDuration(total)}`;

  function toggleActivity() {
    setIsActivityOpen((isOpen) => !isOpen);
  }

  function changeEstimate(minutes: number) {
    actions.changeEstimate(member.id, minutes);
  }

  return (
    <div
      className={cn(
        MEMBER_GRID,
        MEMBER_CARD_HEIGHT,
        'bg-card hairline-ring ring-border relative rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        member.isCurrentUser && OWN_CARD
      )}
    >
      <div className='col-span-3 flex min-w-0 items-center gap-3 py-3 pr-12 pl-4 xl:col-span-1 xl:pr-4'>
        <PresenceAvatar member={member} />
        <div className='flex min-w-0 flex-col gap-0.5'>
          <p className='flex min-w-0 items-center gap-2 text-[13px] font-medium'>
            <span className='truncate'>{member.name}</span>
            {member.isCurrentUser && (
              <Chip color='var(--muted-foreground)'>You</Chip>
            )}
          </p>
          <p className='text-muted-foreground truncate text-xs'>
            {member.title}
            {isManager && ' · Manager'}
          </p>
        </div>
      </div>
      <div className='xl:hairline-l border-border col-span-3 flex min-w-0 items-center px-4 pb-3 xl:col-span-1 xl:py-3'>
        <TaskCell member={member} openTasks={openTasks} actions={actions} />
      </div>
      <div className='hairline-t xl:hairline-l border-border flex flex-col justify-center gap-1 border-dashed px-4 py-3 xl:items-center xl:border-t-0 xl:border-solid'>
